NAME = 'VulgSistine: Vulgata Sistina'
BOOK = 'Hebrews'

CHAPTERS = {
    1: {
        1: 'Multifariam, multisque modis olim Deus loquens patribus in Prophetis:',
        2: 'novissime, diebus istis locutus est nobis in Filio, quem constituit heredem universorum, per quem fecit et saecula:',
        3: 'qui cum sit splendor gloriae, et figura substantiae eius, portansque omnia verbo virtutis suae, purgationem peccatorum faciens, sedet ad dexteram maiestatis in excelsis:',
        4: 'tanto melior Angelis effectus, quanto differentius prae illis nomen hereditavit.',
        5: 'Cui enim dixit aliquando Angelorum: Filius meus es tu, ego hodie genui te? Et rursum: Ego ero illi in patrem, et ipse erit mihi in filium?',
        6: 'Et cum iterum introducit primogenitum in orbem terrae, dicit: Et adorent eum omnes Angeli Dei.',
        7: 'Et ad Angelos quidem dicit: Qui facit Angelos suos spiritus, et ministros suos flammam ignis.',
        8: 'Ad filium autem: Thronus tuus Deus in saeculum saeculi: virga aequitatis, virga regni tui.',
        9: 'Dilexisti iustitiam, et odisti iniquitatem: propterea unxit te Deus, Deus tuus oleo exultationis prae participibus tuis.',
        10: 'Et: Tu in principio Domine terram fundasti: et opera manuum tuarum sunt caeli.',
        11: 'Ipsi peribunt, tu autem permanebis, et omnes ut vestimentum veterascent:',
        12: 'et velut amictum mutabis eos, et mutabuntur: tu autem idem ipse es, et anni tui non deficient.',
        13: 'Ad quem autem Angelorum dixit aliquando: Sede a dextris meis, quoadusque ponam inimicos tuos scabellum pedum tuorum?',
        14: 'Nonne omnes sunt administratorii spiritus, in ministerium missi propter eos, qui hereditatem capiunt salutis?',
    },
    2: {
        1: 'Propterea abundantius oportet observare nos ea, quae audivimus ne forte pereffluamus.',
        2: 'Si enim qui per Angelos dictus est sermo, factus est firmus, et omnis praevaricatio, et inobedientia accepit iustam mercedis retributionem:',
        3: 'quomodo nos effugiemus si tantam neglexerimus salutem? quae cum initium accepisset enarrari per Dominum ab eis, qui audierunt, in nos confirmata est,',
        4: 'contestante Deo signis et portentis, et variis virtutibus, et Spiritus sancti distributionibus secundum suam voluntatem.',
        5: 'Non enim Angelis subiecit Deus orbem terrae futurum, de quo loquimur.',
        6: 'Testatus est autem in quodam loco quis, dicens: Quid est homo quod memor es eius, aut filius hominis quoniam visitas eum?',
        7: 'Minuisti eum paulominus ab Angelis: gloria et honore coronasti eum: et constituisti eum super opera manuum tuarum.',
        8: 'Omnia subiecisti sub pedibus eius: In eo enim quod omnia ei subiecit, nihil dimisit non subiectum ei. Nunc autem necdum videmus omnia subiecta ei.',
        9: 'Eum autem, qui modico quam Angeli minoratus est, videmus Iesum propter passionem mortis, gloria et honore coronatum: ut gratia Dei, pro omnibus gustaret mortem.',
        10: 'Decebat enim eum, propter quem omnia, et per quem omnia, qui multos filios in gloriam adduxerat, auctorem salutis eorum per passionem consummari.',
        11: 'Qui enim sanctificat, et qui sanctificantur, ex uno omnes. Propter quam causam non confunditur fratres eos vocare, dicens:',
        12: 'Nunciabo nomen tuum fratribus meis: in medio Ecclesiae laudabo te.',
        13: 'Et iterum: Ego ero fidens in eum. Et iterum: Ecce ego, et pueri mei, quos dedit mihi Deus.',
        14: 'Quia ergo pueri communicaverunt carni, et sanguini, et ipse similiter participavit eisdem: ut per mortem destrueret eum, qui habebat mortis imperium, id est, diabolum:',
        15: 'et liberaret eos, qui timore mortis per totam vitam obnoxii erant servituti.',
        16: 'Nusquam enim Angelos apprehendit, sed semen Abrahae apprehendit.',
        17: 'Unde debuit per omnia fratribus similari, ut misericors fieret, et fidelis pontifex ad Deum, et ut repropitiaret delicta populi.',
        18: 'In eo enim, in quo passus est ipse et tentatus, potens est et eis, qui tentantur, auxiliari.',
    },
    3: {
        1: 'Unde fratres sancti, vocationis caelestis participes, considerate Apostolum, et pontificem confessionis nostrae Iesum:',
        2: 'qui fidelis est ei, qui praefecit illum sicut et Moyses in omni domo eius.',
        3: 'Amplioris enim gloriae iste prae Moyse dignus est habitus, quanto ampliorem honorem habet domus, qui fabricavit illam.',
        4: 'Omnis namque domus fabricatur ab aliquo: qui autem omnia creavit, Deus est.',
        5: 'Et Moyses quidem fidelis erat in tota domo eius tamquam famulus, in testimonium eorum, quae dicenda erant:',
        6: 'Christus vero tamquam filius in domo sua: quae domus sumus nos, si fiduciam, et gloriam spei usque ad finem, firmam retineamus.',
        7: 'Quapropter sicut dicit Spiritus sanctus: Hodie si vocem eius audieritis,',
        8: 'nolite obdurare corda vestra, sicut in exacerbatione secundum diem tentationis in deserto,',
        9: 'ubi tentaverunt me patres vestri: probaverunt, et viderunt opera mea',
        10: 'quadraginta annis: Propter quod infensus fui generationi huic, et dixi: Semper errant corde. Ipsi autem non cognoverunt vias meas,',
        11: 'quibus iuravi in ira mea: Si introibunt in requiem meam.',
        12: 'Videte fratres, ne forte sit in aliquo vestrum cor malum incredulitatis, discedendi a Deo vivo:',
        13: 'sed adhortamini vosmetipsos per singulos dies, donec Hodie cognominatur, ut non obduretur quis ex vobis fallacia peccati.',
        14: 'Participes enim Christi effecti sumus: si tamen initium substantiae eius usque ad finem firmum retineamus.',
        15: 'Dum dicitur: Hodie si vocem eius audieritis, nolite obdurare corda vestra, quemadmodum in illa exacerbatione.',
        16: 'Quidam enim audientes exacerbaverunt: sed non universi qui profecti sunt ex Aegypto per Moysen.',
        17: 'Quibus autem infensus est quadraginta annis? Nonne illis, qui peccaverunt, quorum cadavera prostrata sunt in deserto?',
        18: 'Quibus autem iuravit non introire in requiem ipsius, nisi illis, qui increduli fuerunt?',
        19: 'Et videmus, quia non potuerunt introire in requiem ipsius propter incredulitatem.',
    },
    4: {
        1: 'Timeamus ergo ne forte relicta pollicitatione introeundi in requiem eius, existimetur aliquis ex nobis deesse.',
        2: 'Etenim et nobis nunciatum est, quemadmodum et illis. sed non profuit illis sermo auditus, non admistus fidei ex iis, quae audierunt.',
        3: 'Ingrediemur enim in requiem, qui credidimus: quemadmodum dixit: Quibus iuravi in ira mea: Si introibunt in requiem meam: et quidem operibus ab institutione mundi perfectis.',
        4: 'Dixit enim in quodam loco de die septima sic: Et requievit Deus die septima ab omnibus operibus suis.',
        5: 'Et in isto rursum: Si introibunt in requiem meam.',
        6: 'Quoniam ergo superest introire quosdam in illam, et ii, quibus prioribus annunciatum est, non introierunt propter incredulitatem:',
        7: 'iterum terminat diem quendam, Hodie, in David dicendo, post tantum temporis, sicut supra dictum est: Hodie si vocem eius audieritis, nolite obdurare corda vestra.',
        8: 'Nam si eis Iesus requiem praestitisset, numquam de alia loqueretur, posthac, die.',
        9: 'Itaque relinquitur sabbatismus populo Dei.',
        10: 'Qui enim ingressus est in requiem eius: etiam ipse requievit ab operibus suis, sicut a suis Deus.',
        11: 'Festinemus ergo ingredi in illam requiem: ut ne in idipsum quis incidat incredulitatis exemplum.',
        12: 'Vivus est enim sermo Dei, et efficax, et penetrabilior omni gladio ancipiti: et pertingens usque ad divisionem animae ac spiritus, compagum quoque ac medullarum, et discretor cogitationum et intentionum cordis.',
        13: 'Et non est ulla creatura invisibilis in conspectu eius: omnia enim nuda et aperta sunt oculis eius, ad quem nobis sermo.',
        14: 'Habentes ergo pontificem magnum, qui penetravit caelos, Iesum Filium Dei: teneamus spei nostrae confessionem.',
        15: 'Non enim habemus pontificem, qui non possit compati infirmitatibus nostris: tentatum autem per omnia pro similitudine absque peccato.',
        16: 'Adeamus ergo cum fiducia ad thronum gratiae eius: ut misericordiam consequamur, et gratiam inveniamus in auxilio opportuno.',
    },
    5: {
        1: 'Omnis namque Pontifex ex hominibus assumptus, pro hominibus constituitur in iis, quae sunt ad Deum, ut offerat dona, et sacrificia pro peccatis:',
        2: 'qui condolere possit iis, qui ignorant, et errant: quoniam et ipse circumdatus est infirmitate:',
        3: 'et propterea debet, quemadmodum pro populo, ita etiam et pro semetipso offerre pro peccatis.',
        4: 'Nec quisquam sumit sibi honorem, sed qui vocatur a Deo, tamquam Aaron.',
        5: 'Sic et Christus non semetipsum clarificavit ut pontifex fieret: sed qui locutus est ad eum: Filius meus es tu, ego hodie genui te.',
        6: 'Quemadmodum et in alio loco dicit: Tu es sacerdos in aeternum, secundum ordinem Melchisedech.',
        7: 'Qui in diebus carnis suae preces, supplicationesque ad eum, qui possit illum salvum facere a morte cum clamore valido, et lacrymis offerens, exauditus est pro sua reverentia:',
        8: 'Et quidem cum esset Filius Dei, didicit ex iis, quae passus est, obedientiam:',
        9: 'et consummatus, factus est omnibus obtemperantibus sibi, causa salutis aeternae,',
        10: 'appellatus a Deo pontifex iuxta ordinem Melchisedech.',
        11: 'De quo nobis grandis sermo, et interpretabilis ad dicendum: quoniam imbecilles facti estis ad audiendum.',
        12: 'Etenim cum deberetis magistri esse propter tempus: rursum indigetis ut vos doceamini quae sint elementa exordii sermonum Dei: et facti estis quibus lacte opus sit, non solido cibo.',
        13: 'Omnis enim, qui lactis est particeps, expers est sermonis iustitiae, parvulus enim est.',
        14: 'Perfectorum autem est solidus cibus: eorum, qui pro consuetudine exercitatos habent sensus ad discretionem boni ac mali.',
    },
    6: {
        1: 'Quapropter intermittentes inchoationis Christi sermonem, ad perfectiora feramur, non rursum iacientes fundamentum poenitentiae ab operibus mortuis, et fidei ad Deum,',
        2: 'baptismatum doctrinae, impositionis quoque manuum, ac resurrectionis mortuorum, et iudicii aeterni.',
        3: 'Et hoc faciemus, si quidem permiserit Deus.',
        4: 'Impossibile est enim eos, qui semel sunt illuminati, gustaverunt etiam donum caeleste, et participes facti sunt Spiritus sancti,',
        5: 'gustaverunt nihilominus bonum Dei verbum, virtutesque saeculi venturi,',
        6: 'et prolapsi sunt; rursus renovari ad poenitentiam, rursum crucifigentes sibimetipsis filium Dei, et ostentui habentes.',
        7: 'Terra enim saepe venientem super se bibens imbrem, et germinans herbam opportunam illis, a quibus colitur: accipit benedictionem a Deo.',
        8: 'proferens autem spinas, ac tribulos, reproba est, et maledicto proxima: cuius consummatio in combustionem.',
        9: 'Confidimus autem de vobis dilectissimi meliora, et viciniora saluti: tametsi ita loquimur.',
        10: 'Non enim iniustus est Deus, ut obliviscatur operis vestri, et dilectionis, quam ostendistis in nomine ipsius, qui ministrastis sanctis, et ministratis.',
        11: 'Cupimus autem unumquemque vestrum eandem ostentare solicitudinem ad expletionem spei usque in finem:',
        12: 'ut non segnes efficiamini, verum imitatores eorum, qui fide, et patientia hereditabunt promissiones.',
        13: 'Abrahae namque promittens Deus, quoniam neminem habuit, per quem iuraret, maiorem, iuravit per semetipsum,',
        14: 'dicens: Nisi benedicens benedicam te, et multiplicans multiplicabo te.',
        15: 'Et sic longanimiter ferens, adeptus est repromissionem.',
        16: 'Homines enim per maiorem sui iurant: et omnis controversiae eorum finis, ad confirmationem, est iuramentum.',
        17: 'In quo abundantius volens Deus ostendere pollicitationis heredibus immobilitatem consilii sui, interposuit iusiurandum:',
        18: 'ut per duas res immobiles, quibus impossibile est mentiri Deum, fortissimum solatium habeamus, qui confugimus ad tenendam propositam spem,',
        19: 'quam sicut anchoram habemus animae tutam ac firmam, et incedentem usque ad interiora velaminis,',
        20: 'ubi praecursor pro nobis introivit Iesus, secundum ordinem Melchisedech pontifex factus in aeternum.',
    },
    7: {
        1: 'Hic enim Melchisedech, rex Salem, sacerdos Dei summi, qui obviavit Abrahae regresso a caede regum, et benedixit ei:',
        2: 'cui et decimas omnium divisit Abraham: primum quidem qui interpretatur rex iustitiae: deinde autem et rex Salem, quod est, rex pacis,',
        3: 'sine patre, sine matre, sine genealogia, neque initium dierum, neque finem vitae habens, assimilatus autem Filio Dei, manet sacerdos in perpetuum.',
        4: 'Intuemini autem quantus sit hic, cui et decimas dedit de praecipuis Abraham patriarcha.',
        5: 'Et quidem de filiis Levi sacerdotium accipientes, mandatum habent decimas sumere a populo secundum legem, id est, a fratribus suis: quamquam et ipsi exierint de lumbis Abrahae.',
        6: 'Cuius autem generatio non annumeratur in eis, decimas sumpsit ab Abraham, et hunc, qui habebat repromissiones, benedixit.',
        7: 'Sine ulla autem contradictione, quod minus est, a meliore benedicitur.',
        8: 'Et hic quidem, decimas morientes homines accipiunt: ibi autem contestatur, quia vivit.',
        9: 'Et (ut ita dictum sit) per Abraham, et Levi, qui decimas accepit, decimatus est:',
        10: 'adhuc enim in lumbis patris erat, quando obviavit ei Melchisedech.',
        11: 'Si ergo consummatio per sacerdotium Leviticum erat (populus enim sub ipso legem accepit) quid adhuc necessarium fuit secundum ordinem Melchisedech, alium surgere sacerdotem, et non secundum ordinem Aaron dici?',
        12: 'Translato enim sacerdotio, necesse est ut et legis translatio fiat.',
        13: 'In quo enim haec dicuntur, de alia tribu est, de qua nullus altari praesto fuit.',
        14: 'Manifestum est enim quod ex Iuda ortus sit Dominus noster: in qua tribu nihil de sacerdotibus Moyses locutus est.',
        15: 'Et amplius adhuc manifestum est: si secundum similitudinem Melchisedech exurgat alius sacerdos,',
        16: 'qui non secundum legem mandati carnalis factus est, sed secundum virtutem vitae insolubilis.',
        17: 'Contestatur enim: Quoniam tu es sacerdos in aeternum, secundum ordinem Melchisedech.',
        18: 'Reprobatio quidem fit praecedentis mandati, propter infirmitatem eius, et inutilitatem:',
        19: 'nihil enim ad perfectum adduxit lex: introductio vero melioris spei, per quam proximamus ad Deum.',
        20: 'Et quantum est non sine iureiurando (alii quidem sine iureiurando sacerdotes facti sunt,',
        21: 'hic autem cum iureiurando per eum, qui dixit ad illum: Iuravit Dominus, et non poenitebit eum: tu es sacerdos in aeternum):',
        22: 'in tantum melioris testamenti sponsor factus est Iesus.',
        23: 'Et alii quidem plures facti sunt sacerdotes secundum legem, idcirco quod morte prohiberentur permanere:',
        24: 'hic autem eo quod maneat in aeternum, sempiternum habet sacerdotium.',
        25: 'Unde et salvare in perpetuum potest accedens per semetipsum ad Deum: semper vivens ad interpellandum pro nobis.',
        26: 'Talis enim decebat ut nobis esset pontifex, sanctus, innocens, impollutus, segregatus a peccatoribus, et excelsior caelis factus:',
        27: 'qui non habet necessitatem quotidie, quemadmodum sacerdotes, prius pro suis delictis hostias offerre, deinde pro populi: hoc enim fecit semel, seipsum offerendo.',
        28: 'Lex enim homines constituit sacerdotes infirmitatem habentes: sermo autem iurisiurandi, qui post legem est, Filium in aeternum perfectum.',
    },
    8: {
        1: 'Capitulum autem super ea, quae dicuntur: Talem habemus Pontificem, qui consedit in dextera sedis magnitudinis in caelis,',
        2: 'sanctorum minister, et tabernaculi veri, quod fixit Deus, et non homo.',
        3: 'Omnis enim pontifex ad offerendum munera, et hostias constituitur: unde necesse est et hunc habere aliquid, quod offerat:',
        4: 'si ergo esset super terram, nec esset sacerdos: cum essent qui offerent secundum legem munera,',
        5: 'qui exemplari, et umbrae deserviunt caelestium. Sicut responsum est Moysi, cum consummaret tabernaculum: Vide (inquit) omnia facito secundum exemplar, quod tibi ostensum est in monte.',
        6: 'Nunc autem melius sortitus est ministerium, quanto et melioris testamenti mediator est, quod in melioribus repromissionibus sancitum est.',
        7: 'Nam si illud prius culpa vacasset: non utique secundi locus inquireretur.',
        8: 'Vituperans enim eos dicit: Ecce dies venient, dicit Dominus: et consummabo super domum Israel, et super domum Iuda testamentum novum,',
        9: 'non secundum testamentum, quod feci patribus eorum in die, qua apprehendi manum eorum ut educerem illos de Terra Aegypti: quoniam ipsi non permanserunt in testamento meo: et ego neglexi eos, dicit Dominus:',
        10: 'Quia hoc est testamentum, quod disponam domui Israel post dies illos, dicit Dominus: Dabo leges meas in mentem eorum, et in corde eorum superscribam eas: et ero eis in Deum, et ipsi erunt mihi in populum:',
        11: 'et non docebit unusquisque proximum suum, et unusquisque fratrem suum, dicens: Cognosce Dominum: quoniam omnes scient me a minore usque ad maiorem eorum:',
        12: 'quia propitius ero iniquitatibus eorum, et peccatorum eorum iam non memorabor.',
        13: 'Dicendo autem novum: veteravit prius. Quod autem antiquatur, et senescit, prope interitum est.',
    },
    9: {
        1: 'Habuit quidem et prius, iustificationes culturae, et Sanctum saeculare.',
        2: 'Tabernaculum enim factum est primum, in quo erant candelabra, et mensa, et propositio panum, quae dicitur Sancta.',
        3: 'Post velamentum autem secundum, tabernaculum, quod dicitur Sancta sanctorum:',
        4: 'aureum habens turibulum, et arcam testamenti circumtectam ex omni parte auro, in qua urna aurea habens manna, et virga Aaron, quae fronduerat, et tabulae testamenti,',
        5: 'superque eam erant Cherubim gloriae obumbrantia propitiatorium: de quibus non est modo dicendum per singula.',
        6: 'His vero ita compositis: in priori quidem tabernaculo semper introibant sacerdotes, sacrificiorum officia consummantes:',
        7: 'in secundo autem semel in anno solus pontifex non sine sanguine, quem offerret pro sua, et populi ignorantia:',
        8: 'hoc significante Spiritu sancto, nondum propalatam esse sanctorum viam, adhuc priore tabernaculo habente statum.',
        9: 'quae parabola est temporis instantis: iuxta quam munera, et hostiae offeruntur, quae non possunt iuxta conscientiam perfectum facere servientem, solummodo in cibis, et in potibus,',
        10: 'et in variis baptismatibus, et iustitiis carnis usque ad tempus correctionis impositis.',
        11: 'Christus autem assistens pontifex futurorum bonorum, per amplius et perfectius tabernaculum non manufactum, id est, non huius creationis:',
        12: 'neque per sanguinem hircorum, aut vitulorum, sed per proprium sanguinem introivit semel in Sancta, aeterna redemptione inventa.',
        13: 'Si enim sanguis hircorum, et taurorum, et cinis vitulae aspersus inquinatos sanctificat ad emundationem carnis:',
        14: 'quanto magis sanguis Christi, qui per Spiritum sanctum semetipsum obtulit immaculatum Deo, emundabit conscientiam nostram ab operibus mortuis, ad serviendum Deo viventi?',
        15: 'Et ideo novi testamenti mediator est: ut morte intercedente, in redemptionem earum praevaricationum, quae erant sub priori testamento, repromissionem accipiant qui vocati sunt aeternae hereditatis.',
        16: 'Ubi enim testamentum est: mors necesse est intercedat testatoris.',
        17: 'Testamentum enim in mortuis confirmatum est: alioquin nondum valet, dum vivit qui testatus est.',
        18: 'Unde nec primum quidem sine sanguine dedicatum est.',
        19: 'Lecto enim omni mandato legis a Moyse universo populo: accipiens sanguinem vitulorum et hircorum cum aqua et lana coccinea, et hyssopo: ipsum quoque librum, et omnem populum aspersit,',
        20: 'dicens: Hic sanguis testamenti, quod mandavit ad vos Deus.',
        21: 'Etiam tabernaculum, et omnia vasa ministerii sanguine similiter aspersit:',
        22: 'Et omnia pene in sanguine secundum legem mundantur: et sine sanguinis effusione non fit remissio.',
        23: 'Necesse est ergo exemplaria quidem caelestium his mundari: ipsa autem caelestia melioribus hostiis quam istis.',
        24: 'Non enim in manufacta Sancta Iesus introivit exemplaria verorum: sed in ipsum caelum, ut appareat nunc vultui Dei pro nobis:',
        25: 'Neque ut saepe offerat semetipsum, quemadmodum Pontifex intrat in Sancta per singulos annos in sanguine alieno:',
        26: 'alioquin oportebat eum frequenter pati ab origine mundi: nunc autem semel in consummatione saeculorum, ad destitutionem peccati, per hostiam suam apparuit.',
        27: 'Et quemadmodum statutum est hominibus semel mori, post hoc autem iudicium:',
        28: 'sic et Christus semel oblatus est ad multorum exhaurienda peccata: secundo sine peccato apparebit omnibus expectantibus se, in salutem.',
    },
    10: {
        1: 'Umbram enim habens lex futurorum bonorum, non ipsam imaginem rerum: per singulos annos eisdem ipsis hostiis, quas offerunt indesinenter, numquam potest accedentes perfectos facere:',
        2: 'alioquin cessassent offerri: ideo quod nullam haberent ultra conscientiam peccati, cultores semel mundati:',
        3: 'sed in ipsis commemoratio peccatorum per singulos annos fit.',
        4: 'impossibile enim est sanguine taurorum et hircorum auferri peccata.',
        5: 'Ideo ingrediens mundum dicit: Hostiam, et oblationem noluisti: corpus autem aptasti mihi:',
        6: 'holocaustomata pro peccato non tibi placuerunt.',
        7: 'Tunc dixi: Ecce venio: in capite libri scriptum est de me: Ut faciam, Deus, voluntatem tuam.',
        8: 'Superius dicens: Quia hostias, et oblationes, et holocaustomata pro peccato noluisti, nec placita sunt tibi, quae secundum legem offeruntur,',
        9: 'tunc dixi: Ecce venio, ut faciam, Deus, voluntatem tuam: aufert primum, ut sequens statuat.',
        10: 'In qua voluntate sanctificati sumus per oblationem corporis Iesu Christi semel.',
        11: 'Et omnis quidem sacerdos praesto est quotidie ministrans, et easdem saepe offerens hostias, quae numquam possunt auferre peccata:',
        12: 'hic autem unam pro peccatis offerens hostiam, in sempiternum sedet in dextera Dei,',
        13: 'de cetero expectans donec ponantur inimici eius scabellum pedum eius.',
        14: 'Una enim oblatione, consummavit in sempiternum sanctificatos.',
        15: 'Contestatur autem nos et Spiritus sanctus. Postquam enim dixit:',
        16: 'Hoc autem testamentum, quod testabor ad illos post dies illos, dicit Dominus: Dabo leges meas in cordibus eorum, et in mentibus eorum superscribam eas:',
        17: 'et peccatorum, et iniquitatum eorum iam non recordabor amplius.',
        18: 'Ubi autem horum remissio: iam non est oblatio pro peccato.',
        19: 'Habentes itaque fratres fiduciam in introitu sanctorum in sanguine Christi,',
        20: 'quam initiavit nobis viam novam, et viventem per velamen, id est, carnem suam,',
        21: 'et sacerdotem magnum super domum Dei:',
        22: 'accedamus cum vero corde in plenitudine fidei, aspersi corda a conscientia mala, et abluti corpus aqua munda,',
        23: 'teneamus spei nostrae confessionem indeclinabilem, (fidelis enim est qui repromisit),',
        24: 'et consideremus invicem in provocationem charitatis, et bonorum operum:',
        25: 'non deserentes collectionem nostram, sicut consuetudinis est quibusdam, sed consolantes, et tanto magis quanto videritis appropinquantem diem.',
        26: 'Voluntarie enim peccantibus nobis post acceptam notitiam veritatis, iam non relinquitur pro peccatis hostia,',
        27: 'terribilis autem quaedam expectatio iudicii, et ignis aemulatio, quae consumptura est adversarios.',
        28: 'Irritam quis faciens legem Moysi, sine ulla miseratione duobus vel tribus testibus moritur:',
        29: 'quanto magis putatis deteriora mereri supplicia qui filium Dei conculcaverit, et sanguinem testamenti pollutum duxerit, in quo sanctificatus est, et spiritui gratiae contumeliam fecerit?',
        30: 'Scimus enim qui dixit: Mihi vindictam, et ego retribuam. Et iterum: Quia iudicabit Dominus populum suum.',
        31: 'Horrendum est incidere in manus Dei viventis.',
        32: 'Rememoramini autem pristinos dies, in quibus illuminati, magnum certamen sustinuistis passionum:',
        33: 'et in altero quidem opprobriis, et tribulationibus spectaculum facti: in altero autem socii taliter conversantium effecti.',
        34: 'Nam et vinctis compassi estis, et rapinam bonorum vestrorum cum gaudio suscepistis, cognoscentes vos habere meliorem, et manentem substantiam.',
        35: 'Nolite itaque amittere confidentiam vestram, quae magnam habet remunerationem.',
        36: 'Patientia enim vobis necessaria est: ut voluntatem Dei facientes, reportetis promissionem.',
        37: 'Adhuc enim modicum aliquantulumque, qui venturus est, veniet, et non tardabit.',
        38: 'iustus autem meus ex fide vivit. quod si subtraxerit se, non placebit animae meae.',
        39: 'Nos autem non sumus subtractionis filii in perditionem, sed fidei in acquisitionem animae.',
    },
    11: {
        1: 'Est autem fides sperandarum substantia rerum, argumentum non apparentium.',
        2: 'In hac enim testimonium consecuti sunt senes.',
        3: 'Fide intelligimus aptata esse saecula verbo Dei: ut ex invisibilibus visibilia fierent.',
        4: 'Fide plurimam hostiam Abel, quam Cain, obtulit Deo, per quam testimonium consecutus est esse iustus, testimonium perhibente muneribus eius Deo, et per illam defunctus adhuc loquitur.',
        5: 'Fide Henoch translatus est ne videret mortem, et non inveniebatur: quia transtulit illum Deus: ante translationem enim testimonium habuit placuisse Deo.',
        6: 'Sine fide autem impossibile est placere Deo. Credere enim oportet accedentem ad Deum quia est, et inquirentibus se remunerator sit.',
        7: 'Fide Noe responso accepto de iis, quae adhuc non videbantur, metuens aptavit arcam in salutem domus suae, per quam damnavit mundum: et iustitiae, quae per fidem est, heres est institutus.',
        8: 'Fide qui vocatur Abraham obedivit in locum exire, quem accepturus erat in hereditatem: et exiit, nesciens quo iret.',
        9: 'Fide demoratus est in Terra repromissionis, tamquam in aliena, in casulis habitando cum Isaac, et Iacob coheredibus repromissionis eiusdem.',
        10: 'Expectabat enim fundamenta habentem civitatem: cuius artifex, et conditor Deus.',
        11: 'Fide et ipsa Sara sterilis virtutem in conceptione seminis accepit, etiam praeter tempus aetatis: quoniam fidelem credidit esse eum, qui repromiserat.',
        12: 'Propter quod et ab uno orti sunt (et hoc emortuo) tamquam sidera caeli in multitudinem, et sicut arena, quae est ad oram maris, innumerabilis.',
        13: 'Iuxta fidem defuncti sunt omnes isti, non acceptis repromissionibus, sed a longe eas aspicientes, et salutantes, et confitentes quia peregrini, et hospites sunt super terram.',
        14: 'Qui enim haec dicunt, significant se patriam inquirere.',
        15: 'Et si quidem ipsius meminissent de qua exierunt, habebant utique tempus revertendi.',
        16: 'nunc autem meliorem appetunt, id est, caelestem. Ideo non confunditur Deus vocari Deus eorum: paravit enim illis civitatem.',
        17: 'Fide obtulit Abraham Isaac, cum tentaretur, et unigenitum offerebat, in quo susceperat repromissiones;',
        18: 'ad quem dictum est: Quia in Isaac vocabitur tibi semen:',
        19: 'arbitrans quia et a mortuis suscitare potens est Deus: unde eum et in parabolam accepit.',
        20: 'Fide et de futuris benedixit Isaac Iacob, et Esau.',
        21: 'Fide Iacob, moriens, singulos filiorum Ioseph benedixit: et adoravit fastigium virgae eius.',
        22: 'Fide Ioseph, moriens, de profectione filiorum Israel memoratus est, et de ossibus suis mandavit.',
        23: 'Fide Moyses, natus, occultatus est mensibus tribus a parentibus suis, eo quod vidissent elegantem infantem, et non timuerunt regis edictum.',
        24: 'Fide Moyses grandis factus negavit se esse filium filiae Pharaonis,',
        25: 'magis eligens affligi cum populo Dei, quam temporalis peccati habere iucunditatem,',
        26: 'maiores divitias aestimans thesauro Aegyptiorum, improperium Christi: aspiciebat enim in remunerationem.',
        27: 'Fide reliquit Aegyptum, non veritus animositatem regis: invisibilem enim tamquam videns sustinuit.',
        28: 'Fide celebravit pascha, et sanguinis effusionem: ne qui vastabat primitiva, tangeret eos.',
        29: 'Fide transierunt Mare rubrum tamquam per aridam terram: quod experti Aegyptii, devorati sunt.',
        30: 'Fide muri Iericho corruerunt, circuitu dierum septem.',
        31: 'Fide Rahab meretrix non periit cum incredulis, excipiens exploratores cum pace.',
        32: 'Et quid adhuc dicam? Deficiet enim me tempus enarrantem de Gedeon, Barac, Samson, Iephte, David, Samuel, et Prophetis:',
        33: 'qui per fidem vicerunt regna, operati sunt iustitiam, adepti sunt repromissiones, obturaverunt ora leonum,',
        34: 'extinxerunt impetum ignis, effugaverunt aciem gladii, convaluerunt de infirmitate, fortes facti sunt in bello, castra verterunt exterorum:',
        35: 'acceperunt mulieres de resurrectione mortuos suos: alii autem distenti sunt non suscipientes redemptionem, ut meliorem invenirent resurrectionem.',
        36: 'Alii vero ludibria, et verbera experti, insuper et vincula, et carceres:',
        37: 'lapidati sunt, secti sunt, tentati sunt, in occisione gladii mortui sunt, circuierunt in melotis, in pellibus caprinis, egentes, angustiati, afflicti:',
        38: 'quibus dignus non erat mundus: in solitudinibus errantes, in montibus, in speluncis, et in cavernis terrae.',
        39: 'Et hi omnes testimonio fidei probati, non acceperunt repromissionem,',
        40: 'Deo pro nobis melius aliquid providente, ut non sine nobis consummarentur.',
    },
    12: {
        1: 'Ideoque et nos tantam habentes impositam nubem testium, deponentes omne pondus, et circumstans nos peccatum, per patientiam curramus ad propositum nobis certamen:',
        2: 'aspicientes in Auctorem fidei, et consummatorem Iesum, qui proposito sibi gaudio sustinuit crucem, confusione contempta, atque in dextera sedis Dei sedet.',
        3: 'Recogitate enim eum, qui talem sustinuit a peccatoribus adversum semetipsum contradictionem: ut ne fatigemini, animis vestris deficientes.',
        4: 'Nondum enim usque ad sanguinem restitistis, adversus peccatum repugnantes:',
        5: 'et obliti estis consolationis, quae vobis tamquam filiis loquitur, dicens: Fili mi, noli negligere disciplinam Domini: neque fatigeris dum ab eo argueris.',
        6: 'Quem enim diligit Dominus, castigat: flagellat autem omnem filium, quem recipit.',
        7: 'In disciplina perseverate. Tamquam filiis vobis offert se Deus: quis enim filius, quem non corripit pater?',
        8: 'Quod si extra disciplinam estis, cuius participes facti sunt omnes: ergo adulteri, et non filii estis.',
        9: 'Deinde patres quidem carnis nostrae, eruditores habuimus, et reverebamur eos. non multo magis obtemperabimus Patri spirituum, et vivemus?',
        10: 'Et illi quidem in tempore paucorum dierum, secundum voluntatem suam erudiebant nos: hic autem ad id, quod utile est in recipiendo sanctificationem eius.',
        11: 'Omnis autem disciplina in praesenti quidem videtur non esse gaudii, sed moeroris: postea autem fructum pacatissimum exercitatis per eam, reddet iustitiae.',
        12: 'Propter quod remissas manus, et soluta genua, erigite,',
        13: 'et gressus rectos facite pedibus vestris: ut non claudicans quis erret, magis autem sanetur.',
        14: 'Pacem sequimini cum omnibus, et sanctimoniam, sine qua nemo videbit Deum:',
        15: 'contemplantes nequis desit gratiae Dei: nequa radix amaritudinis sursum germinans impediat, et per illam inquinentur multi.',
        16: 'Ne quis fornicator, aut profanus ut Esau: qui propter unam escam vendidit primitiva sua:',
        17: 'scitote enim quoniam et postea cupiens hereditare benedictionem, reprobatus est: non enim invenit poenitentiae locum, quamquam cum lacrymis inquisisset eam.',
        18: 'Non enim accessistis ad tractabilem montem, et accessibilem ignem, et turbinem, et caliginem, et procellam,',
        19: 'et tubae sonum, et vocem verborum, quam qui audierunt, excusaverunt se, ne eis fieret verbum.',
        20: 'Non enim portabant quod dicebatur: Et si bestia tetigerit montem, lapidabitur.',
        21: 'Et ita terribile erat quod videbatur. Moyses dixit: Exterritus sum, et tremebundus.',
        22: 'Sed accessistis ad Sion montem, et civitatem Dei viventis, Ierusalem caelestem, et multorum millium Angelorum frequentiam,',
        23: 'et Ecclesiam primitivorum, qui conscripti sunt in caelis, et iudicem omnium Deum, et spiritum iustorum perfectorum,',
        24: 'et testamenti novi mediatorem Iesum, et sanguinis aspersionem melius loquentem quam Abel.',
        25: 'Videte ne recusetis loquentem. Si enim illi non effugerunt, recusantes eum, qui super terram loquebatur: multo magis nos, qui de caelis loquentem nobis avertimus.',
        26: 'cuius vox movit terram tunc: nunc autem repromittit, dicens: Adhuc semel: et ego movebo non solum terram, sed et caelum.',
        27: 'Quod autem, Adhuc semel, dicit: declarat mobilium translationem tamquam factorum, ut maneant ea, quae sunt immobilia.',
        28: 'Itaque regnum immobile suscipientes, habemus gratiam: per quam serviamus placentes Deo, cum metu et reverentia.',
        29: 'Etenim Deus noster ignis consumens est.',
    },
    13: {
        1: 'Charitas fraternitatis maneat in vobis.',
        2: 'Et hospitalitatem nolite oblivisci, per hanc enim placuerunt quidam, Angelis hospitio receptis.',
        3: 'Mementote vinctorum, tamquam simul vincti: et laborantium, tamquam et ipsi in corpore morantes.',
        4: 'Honorabile connubium in omnibus, et thorus immaculatus. Fornicatores enim, et adulteros iudicabit Deus.',
        5: 'Sint mores sine avaritia, contenti praesentibus: ipse enim dixit: Non te deseram, neque derelinquam.',
        6: 'Ita ut confidenter dicamus: Dominus mihi adiutor: non timebo quid faciat mihi homo.',
        7: 'Mementote praepositorum vestrorum, qui vobis locuti sunt verbum Dei: quorum intuentes exitum conversationis, imitamini fidem.',
        8: 'Iesus Christus heri, et hodie: ipse et in saecula.',
        9: 'Doctrinis variis, et peregrinis nolite abduci. Optimum est enim gratia stabilire cor, non escis: quae non profuerunt ambulantibus in eis.',
        10: 'Habemus altare, de quo edere non habent potestatem, qui tabernaculo deserviunt.',
        11: 'Quorum enim animalium infertur sanguis pro peccato in Sancta per pontificem, horum corpora cremantur extra castra.',
        12: 'Propter quod et Iesus, ut sanctificaret per suum sanguinem populum, extra portam passus est.',
        13: 'Exeamus igitur ad eum extra castra, improperium eius portantes.',
        14: 'Non enim habemus hic manentem civitatem, sed futuram inquirimus.',
        15: 'Per ipsum ergo offeramus hostiam laudis semper Deo, id est, fructum labiorum confitentium nomini eius.',
        16: 'Beneficentiae autem, et communionis nolite oblivisci: talibus enim hostiis promeretur Deus.',
        17: 'Obedite praepositis vestris, et subiacete eis. Ipsi enim pervigilant quasi rationem pro animabus vestris reddituri, ut cum gaudio hoc faciant, et non gementes: hoc enim non expedit vobis.',
        18: 'Orate pro nobis: confidimus enim quia bonam conscientiam habemus in omnibus bene volentes conversari.',
        19: 'Amplius autem deprecor vos hoc facere, quo celerius restituar vobis.',
        20: 'Deus autem pacis, qui eduxit de mortuis pastorem magnum ovium, in sanguine testamenti aeterni, Dominum nostrum Iesum Christum,',
        21: 'aptet vos in omni bono, ut faciatis eius voluntatem: faciens in vobis quod placeat coram se per Iesum Christum: cui est gloria in saecula saeculorum. Amen.',
        22: 'Rogo autem vos fratres, ut sufferatis verbum solatii. Etenim perpaucis scripsi vobis.',
        23: 'Cognoscite fratrem nostrum Timotheum dimissum: cum quo (si celerius venerit) videbo vos.',
        24: 'Salutate omnes praepositos vestros, et omnes sanctos. Salutant vos de Italia fratres.',
        25: 'Gratia cum omnibus vobis. Amen.',
    },
}
